function BookCoverBoardShearsMaker.init() BookCoverBoardShearsMaker.ironStock=18; BookCoverBoardShearsMaker.bronzeStock=14; BookCoverBoardShearsMaker.woodStock=10; BookCoverBoardShearsMaker.leatherStock=8; BookCoverBoardShearsMaker.silverStock=8; BookCoverBoardShearsMaker.goldStock=6; BookCoverBoardShearsMaker.jewelStock=4; BookCoverBoardShearsMaker.pearlStock=4; BookCoverBoardShearsMaker.productStock={}; BookCoverBoardShearsMaker.buildings={}; BookCoverBoardShearsMaker.maker=nil; BookCoverBoardShearsMaker.activeMaking={}; BookCoverBoardShearsMaker.totalProducts=0; BookCoverBoardShearsMaker.dayTimer=0; print("[BookCoverBoardShearsMaker] Royal Book Cover Board Shears Maker System initialized (6 products, 4 buildings)") end
function BookCoverBoardShearsMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookCoverBoardShearsMaker.maker={name=n or ("Škardar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škardar najet: %s (spretnost: %d)",BookCoverBoardShearsMaker.maker.name,s),"success") end; return true end
function BookCoverBoardShearsMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookCoverBoardShearsMaker.build(id) local ok,e=BookCoverBoardShearsMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookCoverBoardShearsMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookCoverBoardShearsMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookCoverBoardShearsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookCoverBoardShearsMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookCoverBoardShearsMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookCoverBoardShearsMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookCoverBoardShearsMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookCoverBoardShearsMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookCoverBoardShearsMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookCoverBoardShearsMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookCoverBoardShearsMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookCoverBoardShearsMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookCoverBoardShearsMaker.buildings==0 then return false,"Potrebna škardna delavnica" end; if not BookCoverBoardShearsMaker.maker then return false,"Potreben skardar" end; return true end
function BookCoverBoardShearsMaker.make(pt,qty) qty=qty or 1; local ok,e=BookCoverBoardShearsMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookCoverBoardShearsMaker.ironStock=BookCoverBoardShearsMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookCoverBoardShearsMaker.bronzeStock=BookCoverBoardShearsMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookCoverBoardShearsMaker.woodStock=BookCoverBoardShearsMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookCoverBoardShearsMaker.leatherStock=BookCoverBoardShearsMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookCoverBoardShearsMaker.silverStock=BookCoverBoardShearsMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookCoverBoardShearsMaker.goldStock=BookCoverBoardShearsMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookCoverBoardShearsMaker.jewelStock=BookCoverBoardShearsMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookCoverBoardShearsMaker.pearlStock=BookCoverBoardShearsMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookCoverBoardShearsMaker.maker then t=math.max(1,t-math.floor(BookCoverBoardShearsMaker.maker.skill/13)) end; table.insert(BookCoverBoardShearsMaker.activeMaking,{id="bookcoverboardshears_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookCoverBoardShearsMaker.completeMaking(m) local q=1.0+(BookCoverBoardShearsMaker.getQualityBonus()/100); if BookCoverBoardShearsMaker.maker then q=q+(BookCoverBoardShearsMaker.maker.skill/140) end; q=math.min(2.5,q); BookCoverBoardShearsMaker.productStock[m.productType]=(BookCoverBoardShearsMaker.productStock[m.productType] or 0)+m.quantity; BookCoverBoardShearsMaker.totalProducts=BookCoverBoardShearsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookCoverBoardShearsMaker.maker then BookCoverBoardShearsMaker.maker.itemsMade=BookCoverBoardShearsMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookCoverBoardShearsMaker.maker.skill=math.min(100,BookCoverBoardShearsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Škarde izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookcoverboardshears.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookCoverBoardShearsMaker.update(dt) if not _G.state then return end; BookCoverBoardShearsMaker.dayTimer=BookCoverBoardShearsMaker.dayTimer+dt; if BookCoverBoardShearsMaker.dayTimer>=30 then BookCoverBoardShearsMaker.dayTimer=0; for i=#BookCoverBoardShearsMaker.activeMaking,1,-1 do local m=BookCoverBoardShearsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookCoverBoardShearsMaker.completeMaking(m); table.remove(BookCoverBoardShearsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookCoverBoardShearsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookCoverBoardShearsMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
